                    args.toArray());
            List<Map<String, Object>> lineItems =
                    (List<Map<String, Object>>) in.getOrDefault("lineItems", List.of());
            for (Map<String, Object> li : lineItems) {
                jdbc.update(
                        "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
                                + " VALUES (?, ?, ?, ?, ?)",
